import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } } from '@/primitives';
import { } } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();

  // ---------- Plane ----------
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39; // fallback to spec size
    const textNode = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    });
    // Position text slightly above the plane
    textNode.position.set(0, 0, 0.01);
    root.add(textNode);
  }

  // ---------- Primitives ----------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // ---------- Handlers & Cleanup ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (material.map) {
      material.map.dispose();
    }
    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
